// An LLM answer is a sample, not a measurement. Asking once and writing down
// yes or no is how most trackers get this wrong, so every prompt is asked
// several times and only the pattern across those runs is reported.
const settings = $('Read Brand Settings').first().json;

const brand = String(settings['Brand Name'] || '').trim();
const domain = String(settings['Domain'] || '').replace(/^https?:\/\//i, '').replace(/\/$/, '').toLowerCase();
const competitors = String(settings['Competitors'] || '')
  .split(',').map(function (s) { return s.trim(); }).filter(Boolean);
const repeats = Math.max(1, Math.min(5, Number(settings['Repeats Per Prompt'] || 3) || 3));

if (!brand) {
  throw new Error('Brand Name is empty in the Settings tab. Fill that row before running.');
}

const rows = $input.all().map(function (i) { return i.json; })
  .filter(function (r) { return String(r['Active'] || 'yes').toLowerCase() !== 'no'; })
  .filter(function (r) { return String(r['Prompt'] || '').trim().length > 5; });

if (!rows.length) {
  throw new Error('No active prompts found. Add rows to the Prompts tab with Active set to yes.');
}

const items = [];
rows.forEach(function (r, i) {
  const prompt = String(r['Prompt']).trim();
  for (let run = 1; run <= repeats; run += 1) {
    items.push({
      json: {
        promptId: 'p' + (i + 1),
        prompt: prompt,
        run: run,
        brand: brand,
        domain: domain,
        competitors: competitors,
        askedAt: new Date().toISOString(),
      },
    });
  }
});

return items;

// The two engines answer in different shapes, so both are read into one
// record. Two separate things are recorded, because they are not the same
// result: the brand being named in the prose, and the brand's own domain
// being cited as a source the answer was built from.
function hostOf(u) {
  try { return new URL(u).hostname.replace(/^www\./i, '').toLowerCase(); } catch (e) { return ''; }
}

const asked = $('Expand To Repeat Runs').all().map(function (i) { return i.json; });
const out = [];

$input.all().forEach(function (item, idx) {
  const j = item.json || {};
  // Both engine branches are appended, so the context repeats twice over.
  const ctx = asked[idx % asked.length] || {};

  let engine = 'unknown';
  let text = '';
  const cited = [];

  if (j.choices && j.choices[0] && j.choices[0].message) {
    engine = 'Perplexity';
    text = String(j.choices[0].message.content || '');
    (j.citations || j.search_results || []).forEach(function (c) {
      const u = typeof c === 'string' ? c : (c && c.url) || '';
      if (u) cited.push(u);
    });
  }

  if (Array.isArray(j.output)) {
    engine = 'ChatGPT';
    j.output.forEach(function (block) {
      (block.content || []).forEach(function (c) {
        if (c.text) text += c.text;
        (c.annotations || []).forEach(function (a) { if (a.url) cited.push(a.url); });
      });
    });
  }

  if (!text) {
    out.push({ json: Object.assign({}, ctx, { engine: engine, failed: true, named: false, cited: false, citedHosts: [], competitorsFound: [] }) });
    return;
  }

  const lower = text.toLowerCase();
  const citedHosts = Array.from(new Set(cited.map(hostOf).filter(Boolean)));
  const dom = String(ctx.domain || '');

  const named = ctx.brand ? lower.indexOf(String(ctx.brand).toLowerCase()) !== -1 : false;
  const citedSelf = dom ? citedHosts.some(function (h) { return h === dom || h.endsWith('.' + dom); }) : false;

  out.push({
    json: Object.assign({}, ctx, {
      engine: engine,
      failed: false,
      named: named,
      cited: citedSelf,
      answerSnippet: text.slice(0, 500),
      citedHosts: citedHosts,
      competitorsFound: (ctx.competitors || []).filter(function (c) {
        return c && lower.indexOf(String(c).toLowerCase()) !== -1;
      }),
    }),
  });
});

return out;

// Collapse the repeats back into one row per prompt and engine, and say how
// consistently the brand appeared. A single lucky mention out of three runs is
// not visibility, and the stability word is what stops it being read that way.
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return !r.failed; });

if (!rows.length) {
  throw new Error('Every engine call failed. Check the OpenAI and Perplexity credentials.');
}

const runDate = new Date().toISOString().slice(0, 10);
const groups = {};

rows.forEach(function (r) {
  const key = r.promptId + '|' + r.engine;
  if (!groups[key]) groups[key] = { promptId: r.promptId, prompt: r.prompt, engine: r.engine, brand: r.brand, runs: [] };
  groups[key].runs.push(r);
});

return Object.keys(groups).map(function (k) {
  const g = groups[k];
  const n = g.runs.length;
  const named = g.runs.filter(function (r) { return r.named; }).length;
  const cited = g.runs.filter(function (r) { return r.cited; }).length;
  const rate = named / n;

  let stability = 'never';
  if (rate >= 0.99) stability = 'always';
  else if (rate >= 0.5) stability = 'usually';
  else if (rate > 0) stability = 'sometimes';

  const rivals = {};
  g.runs.forEach(function (r) {
    (r.competitorsFound || []).forEach(function (c) { rivals[c] = (rivals[c] || 0) + 1; });
  });

  const hosts = {};
  g.runs.forEach(function (r) {
    (r.citedHosts || []).forEach(function (h) { hosts[h] = (hosts[h] || 0) + 1; });
  });

  return {
    json: {
      resultKey: g.brand + ' | ' + runDate + ' | ' + g.promptId + ' | ' + g.engine,
      runDate: runDate,
      brand: g.brand,
      promptId: g.promptId,
      prompt: g.prompt,
      engine: g.engine,
      runs: n,
      namedIn: named,
      citedIn: cited,
      mentionRate: Math.round(rate * 100),
      citationRate: Math.round(cited / n * 100),
      stability: stability,
      competitorsNamed: Object.keys(rivals).sort(function (a, b) { return rivals[b] - rivals[a]; }).join(', '),
      sourcesCited: Object.keys(hosts).sort(function (a, b) { return hosts[b] - hosts[a]; }).slice(0, 6).join(', '),
      sample: (g.runs[0].answerSnippet || '').slice(0, 300),
    },
  };
});

// One item for the week: the headline numbers, who is being named instead, and
// which domains the answers kept citing.
const rows = $('Score Each Prompt').all().map(function (i) { return i.json; });
const answers = $('Read Mentions And Citations').all().map(function (i) { return i.json; }).filter(function (r) { return !r.failed; });

const runDate = rows[0].runDate;
const brand = rows[0].brand;

const totalRuns = rows.reduce(function (s, r) { return s + r.runs; }, 0);
const namedRuns = rows.reduce(function (s, r) { return s + r.namedIn; }, 0);
const citedRuns = rows.reduce(function (s, r) { return s + r.citedIn; }, 0);

const mentionRate = Math.round(namedRuns / totalRuns * 100);
const citationRate = Math.round(citedRuns / totalRuns * 100);

// Competitors named across every answer, and the domains that kept being cited.
const rivals = {};
const hosts = {};
answers.forEach(function (a) {
  (a.competitorsFound || []).forEach(function (c) { rivals[c] = (rivals[c] || 0) + 1; });
  (a.citedHosts || []).forEach(function (h) {
    if (a.domain && (h === a.domain || h.endsWith('.' + a.domain))) return;
    hosts[h] = (hosts[h] || 0) + 1;
  });
});

const rivalList = Object.keys(rivals).map(function (k) { return { name: k, hits: rivals[k] }; })
  .sort(function (a, b) { return b.hits - a.hits; });
const hostList = Object.keys(hosts).map(function (k) { return { host: k, hits: hosts[k] }; })
  .sort(function (a, b) { return b.hits - a.hits; }).slice(0, 8);

const rivalTotal = rivalList.reduce(function (s, r) { return s + r.hits; }, 0);
const shareOfVoice = (namedRuns + rivalTotal) > 0 ? Math.round(namedRuns / (namedRuns + rivalTotal) * 100) : 0;

const blindSpots = rows.filter(function (r) { return r.mentionRate === 0; });

// Week over week, against whatever the history tab last held for this brand.
const prev = $('Read Last Week').all().map(function (i) { return i.json; })
  .filter(function (r) { return r && r['Brand'] === brand && r['Run Date'] !== runDate && r['Mention Rate'] !== undefined && r['Mention Rate'] !== ''; });
const last = prev.length ? prev[prev.length - 1] : null;
const prevRate = last ? Number(last['Mention Rate']) : NaN;
const delta = isNaN(prevRate) ? null : mentionRate - prevRate;

function esc(s) {
  return String(s === undefined || s === null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const weak = rows.slice().sort(function (a, b) { return a.mentionRate - b.mentionRate; }).slice(0, 10);
const tableRows = weak.map(function (r) {
  return '<tr><td>' + esc(r.prompt) + '</td><td>' + esc(r.engine) + '</td><td align="right">' +
    r.mentionRate + '%</td><td>' + esc(r.stability) + '</td><td>' + esc(r.competitorsNamed) + '</td></tr>';
}).join('');

const html =
  '<h2>AI answer visibility for ' + esc(brand) + '</h2>' +
  '<p>Across ' + totalRuns + ' answers from ChatGPT and Perplexity, ' + esc(brand) + ' was named in ' +
  mentionRate + '% and had its own domain cited in ' + citationRate + '%.' +
  (delta === null ? '' : ' That is ' + (delta >= 0 ? 'up ' : 'down ') + Math.abs(delta) + ' points on the last run.') +
  ' Share of voice against the tracked competitors is ' + shareOfVoice + '%.</p>' +
  (rivalList.length ? '<p>Named most often instead: ' + rivalList.slice(0, 5).map(function (r) {
    return esc(r.name) + ' (' + r.hits + ')'; }).join(', ') + '.</p>' : '') +
  (hostList.length ? '<p>Domains the answers kept citing: ' + hostList.slice(0, 6).map(function (h) {
    return esc(h.host); }).join(', ') + '.</p>' : '') +
  '<h3>Weakest prompts</h3>' +
  '<table border="1" cellpadding="6" cellspacing="0"><tr><th>Prompt</th><th>Engine</th><th>Named</th><th>Stability</th><th>Competitors named</th></tr>' +
  (tableRows || '<tr><td colspan="5">No prompt results.</td></tr>') + '</table>';

return [{
  json: {
    runKey: brand + ' | ' + runDate,
    runDate: runDate,
    brand: brand,
    promptsTracked: rows.length,
    totalRuns: totalRuns,
    mentionRate: mentionRate,
    citationRate: citationRate,
    shareOfVoice: shareOfVoice,
    deltaVsLastRun: delta,
    dropped: delta !== null && delta <= -10,
    topCompetitor: rivalList.length ? rivalList[0].name : '',
    topCitedDomains: hostList.map(function (h) { return h.host; }).join(', '),
    blindSpots: blindSpots.map(function (r) { return r.prompt; }).join(' | '),
    reportHtml: html,
    slackText: '*AI answer visibility, ' + brand + '*\nNamed in ' + mentionRate + '% of ' + totalRuns +
      ' answers, own domain cited in ' + citationRate + '%, share of voice ' + shareOfVoice + '%.' +
      (delta === null ? '' : ' Change on last run: ' + (delta >= 0 ? '+' : '') + delta + ' points.') +
      (rivalList.length ? '\nNamed instead, most often: ' + rivalList[0].name + '.' : '') +
      (blindSpots.length ? '\n' + blindSpots.length + ' prompts where the brand never appeared.' : ''),
  },
}];
